def _looks_like_typing_cast(node: Call) -> bool:
    """Check if the node represents a typing.cast call."""
    if not isinstance(node.func, (Name, Attribute)):
        return False

    if isinstance(node.func, Name):
        return node.func.name == "cast"

    return node.func.attrname == "cast"


def infer_typing_cast(node: Call, context: InferenceContext | None = None) -> Iterator[InferenceResult]:
    """Infer typing.cast call.

    The typing.cast function returns its second argument unchanged, so we just
    need to infer the second argument.
    """
    if len(node.args) != 2:
        raise UseInferenceDefault

    # The second argument is the value to be returned
    yield from node.args[1].infer(context)


